// Dev/staging seed of the marketing store (port of .ref marketing.seed.ts): contacts, leads, activities, tasks, notes,
// segments, templates, campaigns (+ tracked links and recipient queues), sequences, testimonials, referrals, inbox,
// feed, social metrics, ratings, media, counters. Idempotent (skips when leads exist); run after seedAuth.
// shortcut: `W` is a JSON snapshot of web/src/mocks/marketing-world.ts taken 2026-11-18 (timestamps absolute,
// staff ids remapped below); the 2,200 synthetic SME contacts are regenerated by `generate()` (copied from that file).
import { eq, sql } from "drizzle-orm";
import type { PgDatabase, PgQueryResultHKT } from "drizzle-orm/pg-core";
import type { ExtractTablesWithRelations } from "drizzle-orm";
import type * as schema from "../schema";
import { mktRecords } from "../schema/schema-marketing";
import type {
  AutomationRule, AutomationRun, Campaign, Channel, ConsentState, Contact, CrmNote, CrmTask, InboxThread, Lead, LeadActivity,
  Locale, MktNote, MsgTemplate, Referral, Referrer, Segment, Testimonial,
} from "@/domain/marketing/types";
import { evaluate } from "@/domain/marketing/segment";
import { eligibility } from "@/domain/marketing/consent";

type Db = PgDatabase<PgQueryResultHKT, typeof schema, ExtractTablesWithRelations<typeof schema>>;
const NOW = Date.now();
const iso = (offsetMs = 0) => new Date(NOW + offsetMs).toISOString();
const YEAR = new Date(NOW).getUTCFullYear();
function mulberry32(a: number) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// ---- synthetic SME contacts (copy of marketing-world generate())
const DISTRICTS: [string, string][] = [["Gasabo", "Kigali"], ["Kicukiro", "Kigali"], ["Nyarugenge", "Kigali"], ["Musanze", "North"], ["Huye", "South"], ["Rubavu", "West"], ["Rwamagana", "East"]];
const SECTORS = ["retail", "agri", "hospitality", "transport", "services", "manufacturing", "ict"];
const SERVICES = ["company-registration", "vat-registration", "tax-filing", "business-plan", "trademark", "work-permit"];
const LANGS: Locale[] = ["rw", "rw", "rw", "en", "fr"];
const consent = (e: ConsentState, w: ConsentState, s: ConsentState): Record<Channel, ConsentState> => ({ email: e, whatsapp: w, sms: s });
const VAT_SME = { match: 1596, noConsent: 287, optedOut: 19, suppressed: 6 } as const;
function generate(): Contact[] {
  const r = mulberry32(10);
  const pick = <T,>(a: readonly T[]) => a[Math.floor(r() * a.length)];
  const out: Contact[] = [];
  for (let i = 0; i < 2200; i++) {
    const vat = i < VAT_SME.match;
    const [district, province] = pick(DISTRICTS);
    const wa: ConsentState = !vat ? (r() < 0.7 ? "in" : "unknown") : i < VAT_SME.noConsent ? "unknown" : i < VAT_SME.noConsent + VAT_SME.optedOut ? "out" : "in";
    out.push({
      id: i === 0 ? "ct-no-wa" : `ct-${String(i).padStart(4, "0")}`,
      name: `SME contact ${i + 1}`,
      phoneE164: `+25078${String(1_000_000 + i * 37).slice(-7)}`,
      email: r() < 0.8 ? `contact${i + 1}@sme.example.rw` : undefined,
      language: pick(LANGS), sector: pick(SECTORS), district, province,
      size: vat ? (r() < 0.6 ? "small" : "medium") : pick(["micro", "small", "large"] as const),
      servicesUsed: r() < 0.4 ? [pick(SERVICES)] : [], interests: [pick(SERVICES)], obligations: vat ? ["vat"] : r() < 0.3 ? ["paye"] : [],
      lastActiveAt: iso(-Math.floor(r() * 240) * 86_400_000), ltv: Math.floor(r() * 40) * 10_000,
      consent: consent(r() < 0.75 ? "in" : r() < 0.5 ? "out" : "unknown", wa, r() < 0.5 ? "in" : "unknown"),
      suppressed: vat && i >= VAT_SME.noConsent + VAT_SME.optedOut && i < VAT_SME.noConsent + VAT_SME.optedOut + VAT_SME.suppressed,
    });
  }
  return out;
}

