function ratings() {
  const r = mulberry32(42);
  const services = [
    "company-registration",
    "vat-registration",
    "tax-filing",
    "business-plan",
    "trademark",
  ];
  const tags = ["speed", "communication", "price", "clarity", "documents"];
  return Array.from({ length: 64 }, (_, i) => {
    const stars = Math.min(5, Math.max(1, Math.round(3.3 + r() * 2.2)));
    return {
      id: `rt-${i}`,
      stars,
      nps: Math.min(10, Math.max(0, stars * 2 - (r() < 0.5 ? 1 : 0))),
      service: services[i % services.length],
      tag: tags[Math.floor(r() * tags.length)],
      at: iso(-Math.floor(r() * 80) * D),
    };
  }); // demo data, PLACEHOLDER(rating-seed)
}

