export async function seedMarketing(db: Db) {
  const [{ n }] = await db
    .select({ n: sql<number>`count(*)::int` })
    .from(mktRecords)
    .where(eq(mktRecords.kind, "lead"));
  if (Number(n) > 0) return;
  const rows: Row[] = [];
  const add = (
    kind: string,
    xs: { id: string }[],
    o: {
      status?: (x: never) => string | null;
      ref?: (x: never) => string | null | undefined;
    } = {},
  ) =>
    xs.forEach((x, i) =>
      rows.push({
        kind,
        id: x.id,
        pos: i,
        data: remap(x),
        status: o.status?.(x as never) ?? null,
        ref: o.ref?.(x as never) ?? null,
      }),
    );

  add("contact", CONTACTS, {
    status: (c: { clientId?: string }) => (c.clientId ? "customer" : null),
    ref: (c: { clientId?: string }) => c.clientId,
  });
  add("lead", LEADS, {
    status: (l: Lead) => l.stage,
    ref: (l: Lead) => l.clientId,
  });
  add("activity", ACTIVITIES, { ref: (a: { leadId: string }) => a.leadId });
  add("task", TASKS, {
    status: (t: { done: boolean }) => (t.done ? "done" : "open"),
    ref: (t: { subject: { id: string } }) => t.subject.id,
  });
  add("note", NOTES, { ref: (x: { subject: { id: string } }) => x.subject.id });
  add("segment", SEGMENTS);
  add("template", TEMPLATES, {
    status: (t: { status: string }) => t.status,
    ref: (t: { key: string }) => t.key,
  });
  add("campaign", CAMPAIGNS, {
    status: (c: { status: string }) => c.status,
    ref: (c: { slug: string }) => c.slug,
  });
  add("automation", AUTOMATIONS, {
    status: (a: { active: boolean }) => (a.active ? "active" : "inactive"),
  });
  add("run", RUNS, {
    status: (r: { status: string }) => r.status,
    ref: (r: { subject: { id: string } }) => r.subject.id,
  });
  add("testimonial", TESTIMONIALS, {
    status: (t: { status: string }) => t.status,
  });
  add("referrer", REFERRERS, { ref: (r: { id: string }) => r.id });
  add("referral", REFERRALS, { status: (r: { state: string }) => r.state });
  add("thread", THREADS, {
    status: (t: { unread: number }) => (t.unread ? "unread" : "read"),
    ref: (t: { leadId?: string }) => t.leadId,
  });
  add("feed", NOTES_FEED, {
    status: (f: { read: boolean }) => (f.read ? "read" : "unread"),
  });
  add("social", SOCIAL, { ref: (s: { campaign: string }) => s.campaign });
  add("rating", ratings());
  add("media", MEDIA);

  // Tracked links: one per campaign slug; sent campaigns carry their recipient queue for the results tab.
  CAMPAIGNS.forEach((c, i) => {
    rows.push({
      kind: "link",
      id: c.slug,
      pos: i,
      ref: c.id,
      data: {
        code: c.slug,
        target: "/",
        campaign: c.slug,
        campaignId: c.id,
        clicks: c.stats.clicked,
        daily: c.stats.clicked
          ? { [iso(-6 * D).slice(0, 10)]: c.stats.clicked }
          : {},
        sources: c.stats.clicked ? { [c.channel]: c.stats.clicked } : {},
        createdAt: c.createdAt,
      },
    });
    if (!c.stats.sent) return;
    const seg = SEGMENTS.find((s) => s.id === c.segmentId);
    const queue = seg
      ? eligibility(evaluate(seg.definition, CONTACTS), { channel: c.channel })
          .eligible.map((x) => x.id)
          .slice(0, c.stats.queued)
      : [];
    rows.push({
      kind: "cmpx",
      id: c.id,
      pos: i,
      data: remap({
        testSends: 0,
        queue,
        cursor: Math.min(queue.length, c.stats.sent + c.stats.failed),
        failedIds: queue.slice(0, c.stats.failed),
        sentLog: {},
        budgetApproved: false,
        consentDelta: 0,
        timeline: [
          { status: "draft", at: c.createdAt, by: c.createdBy },
          ...(c.approvedAt
            ? [{ status: "approved", at: c.approvedAt, by: c.approvedBy }]
            : []),
          { status: c.status, at: c.scheduledAt ?? c.createdAt },
        ],
      }),
    });
  });
  REFERRERS.forEach((r, i) =>
    rows.push({
      kind: "link",
      id: r.code,
      pos: 100 + i,
      ref: r.id,
      data: {
        code: r.code,
        target: "/",
        referrerId: r.id,
        clicks: r.referred * 3,
        daily: {},
        sources: { referral: r.referred * 3 },
        createdAt: iso(-60 * D),
      },
    }),
  );

  // Counters continue after the seeded ids.
  const counters: Record<string, number> = {
    [`LD-${YEAR}`]: 440,
    [`CP-${YEAR}`]: 24,
    tk: 60,
    nt: 40,
    th: 30,
    rf: 20,
    so: 10,
    md: 10,
    ac: 0,
    n: 0,
  };
  for (const [id, v] of Object.entries(counters))
    rows.push({ kind: "counter", id, pos: 0, data: { n: v } });
  // Month-to-date spend for the budget meter (seed SPEND.month).
  rows.push({
    kind: "setting",
    id: "spend",
    pos: 0,
    data: { month: new Date().toISOString().slice(0, 7), amount: 40_000 },
  });

  for (let i = 0; i < rows.length; i += 500)
    await db
      .insert(mktRecords)
      .values(
        rows
          .slice(i, i + 500)
          .map((r) => ({ ...r, status: r.status ?? null, ref: r.ref ?? null })),
      )
      .onConflictDoNothing();
}
